package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class OptionsHasShortOptionTest {

    // Helper to insert entries into the private shortOpts map via reflection
    private void putShortOpt(final Options options, final String key) throws Exception {
        Field f = Options.class.getDeclaredField("shortOpts");
        f.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<Object, Object> shortOpts = (Map<Object, Object>) f.get(options);
        shortOpts.put(key, new Object());
    }

    @Test
    void testHasShortOption_whenPresent_variationsWithHyphens() throws Exception {
        Options opts = new Options();

        // add short option with key "a"
        putShortOpt(opts, "a");

        // direct, single hyphen and double hyphen should all map to "a"
        assertTrue(opts.hasShortOption("a"), "plain name should be found");
        assertTrue(opts.hasShortOption("-a"), "single hyphen should be normalized and found");
        assertTrue(opts.hasShortOption("--a"), "double hyphen should be normalized and found");
    }

    @Test
    void testHasShortOption_whenAbsent_and_edgeInputs() throws Exception {
        Options opts = new Options();

        // no entries added => all queries should be false
        assertFalse(opts.hasShortOption("b"), "non-existing key should not be found");
        assertFalse(opts.hasShortOption("-"), "single hyphen yields empty string -> not found");
        assertFalse(opts.hasShortOption(""), "empty string not found when not present");
        // null input when map doesn't contain null key
        assertFalse(opts.hasShortOption(null), "null should not be found when no null key present");
    }

    @Test
    void testHasShortOption_withNullAndEmptyKeysPresent() throws Exception {
        Options opts = new Options();

        // insert null and empty string keys into the internal shortOpts map
        putShortOpt(opts, null);
        putShortOpt(opts, "");

        // When null key present
        assertTrue(opts.hasShortOption(null), "null key present should be found");

        // Empty string key present: queries that normalize to empty string should be true
        assertTrue(opts.hasShortOption(""), "empty string key present should be found");
        assertTrue(opts.hasShortOption("-"), "single hyphen normalizes to empty string and should be found");
        assertTrue(opts.hasShortOption("--"), "double hyphen normalizes to empty string and should be found");
    }
}

